/* eslint-disable no-console */
// Build a COMPLETE local news query-index.json for local verification only.
//
// Production's /nz/en/news/query-index.json is generated by AEM from
// helix-query.yaml on publish. The local dev server does NOT build it, so all
// but the two hand-migrated articles are missing locally and most category
// feeds render empty. This script walks every migrated article's local
// .plain.html, reads its Metadata block (Title, Description, Publication Date,
// Tags, Image) plus the yyyy/mm/dd folder date, and emits an index in the same
// shape AEM produces ({ total, offset, limit, data:[…] }).
//
// It is a VERIFICATION FIXTURE, not source-of-truth content. Do not upload it.
//
// Usage: node tools/importer/build-local-index.mjs [--limit=N] [--quiet]

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '../..');
const CONTENT = path.join(REPO_ROOT, 'content/nz/en/news');
const OUT = path.join(CONTENT, 'query-index.json');

const args = process.argv.slice(2);
const limit = Number((args.find((a) => a.startsWith('--limit=')) || '').split('=')[1] || 0);
const quiet = args.includes('--quiet');

// Collect every migrated article .plain.html under the year folders.
const rels = [];
const walk = (d) => {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const fp = path.join(d, e.name);
    if (e.isDirectory()) walk(fp);
    else if (e.name.endsWith('.plain.html')) {
      rels.push(path.relative(CONTENT, fp).replace(/\.plain\.html$/, ''));
    }
  }
};
['2024', '2025', '2026'].forEach((y) => {
  const dir = path.join(CONTENT, y);
  if (fs.existsSync(dir)) walk(dir);
});
rels.sort();

// Strip tags and collapse whitespace to plain text.
const text = (html) => html.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

// From the Metadata block, pull the <div> value that follows a labelled
// <div>Label</div>. The block is a flat list of <div><div>Label</div><div>Value</div></div>.
function metaValue(block, label) {
  // Match a row whose first cell text equals the label, capture the second cell.
  const re = new RegExp(
    `<div>\\s*<div>\\s*${label}\\s*</div>\\s*<div>([\\s\\S]*?)</div>\\s*</div>`,
    'i',
  );
  const m = re.exec(block);
  return m ? m[1] : '';
}

// Extract the Metadata block markup (from the metadata div to end of file).
function metadataBlock(src) {
  const idx = src.search(/<div\s+class="metadata"/i);
  return idx === -1 ? '' : src.slice(idx);
}

// Resolve an Image cell (may contain <img src="./slug/img.jpg">) to a
// site-absolute path matching what AEM emits for og:image.
function resolveImage(cellHtml, dirAbs) {
  const m = /src="([^"]+)"/i.exec(cellHtml);
  if (!m) return '';
  let src = m[1].trim();
  if (src.startsWith('./')) src = src.slice(2);
  if (src.startsWith('/')) return src;
  return `${dirAbs}/${src}`;
}

const splitTags = (s) => text(s).split(',').map((t) => t.trim()).filter(Boolean);

const data = [];
const perTag = {};
let skipped = 0;
let work = rels;
if (limit) work = work.slice(0, limit);

for (const rel of work) {
  const src = path.join(CONTENT, `${rel}.plain.html`);
  let html;
  try {
    html = fs.readFileSync(src, 'utf8');
  } catch {
    skipped += 1;
    continue;
  }
  const block = metadataBlock(html);
  if (!block) { skipped += 1; continue; }

  // Site-absolute path (dev server serves under /content).
  const dirAbs = `/content/nz/en/news/${path.dirname(rel)}`;
  const pathAbs = `/nz/en/news/${rel}`;

  const title = text(metaValue(block, 'Title'));
  const description = text(metaValue(block, 'Description'));
  let publicationDate = text(metaValue(block, 'Publication Date'));
  // Fall back to the yyyy/mm/dd folder date if metadata is missing.
  if (!publicationDate) {
    const dm = /^(\d{4})\/(\d{2})\/(\d{2})\//.exec(rel);
    if (dm) publicationDate = `${dm[1]}-${dm[2]}-${dm[3]}`;
  }
  const tags = splitTags(metaValue(block, 'Tags'));
  const tagPaths = text(metaValue(block, 'Tag Paths'));
  const image = resolveImage(metaValue(block, 'Image'), dirAbs);

  tags.forEach((t) => { perTag[t] = (perTag[t] || 0) + 1; });

  data.push({
    path: pathAbs,
    title,
    image,
    description,
    publicationDate,
    tags,
    tagPaths,
  });
}

const out = {
  total: data.length, offset: 0, limit: data.length, data,
};
fs.writeFileSync(OUT, `${JSON.stringify(out, null, 2)}\n`);

if (!quiet) {
  console.log(`Wrote ${data.length} rows to ${path.relative(REPO_ROOT, OUT)} (skipped ${skipped}).`);
  const sorted = Object.entries(perTag).sort((a, b) => b[1] - a[1]);
  console.log('\nArticles per tag:');
  sorted.forEach(([t, n]) => console.log(`  ${String(n).padStart(5)}  ${t}`));
}
